function pathsWithTotal(root: TreeNode | null, target: number): number[][] {
  const out: number[][] = [];
  if (!root) return out;
  const stack: [TreeNode, number[], number][] = [[root, [root.val], root.val]];
  while (stack.length) {
    const [node, path, sum] = stack.pop()!;
    if (!node.left && !node.right) {
      if (sum === target) out.push(path);
      continue;
    }
    if (node.right) stack.push([node.right, [...path, node.right.val], sum + node.right.val]);
    if (node.left) stack.push([node.left, [...path, node.left.val], sum + node.left.val]);
  }
  return out;
}

