class Solution:
    def pathsWithTotal(self, root: Optional[TreeNode], target: int) -> List[List[int]]:
        out = []
        if not root:
            return out
        stack = [(root, [root.val], root.val)]
        while stack:
            node, path, total = stack.pop()
            if not node.left and not node.right:
                if total == target:
                    out.append(path)
                continue
            for child in (node.right, node.left):
                if child:
                    stack.append((child, path + [child.val], total + child.val))
        return out

