function pathsWithTotal(root: TreeNode | null, target: number): number[][] {
  const out: number[][] = [];
  const path: number[] = [];
  const walk = (node: TreeNode | null, sum: number): void => {
    if (!node) return;
    sum += node.val;
    path.push(node.val);
    if (!node.left && !node.right) {
      if (sum === target) out.push([...path]);
    } else {
      walk(node.left, sum);
      walk(node.right, sum);
    }
    path.pop();
  };
  walk(root, 0);
  return out;
}

